    if approval_mode is ApprovalMode.deny_all:
        return AskForApproval(AskForApprovalValue.never), None
    return (
        AskForApproval(AskForApprovalValue.on_request),
        ApprovalsReviewer.auto_review,
    )


def _resolve_approval_settings(
    approval_mode: ApprovalMode | None,
) -> tuple[AskForApproval | None, ApprovalsReviewer | None]:
    """Return approval params for an optional mode; ``None`` sends nothing."""
    if approval_mode is None:
        return None, None
    return _approval_mode_settings(approval_mode)


